// Ported from cloud-portal app/features/edge/proxy/metrics/queries.ts at a7010d0e: the
// builders the ALB metrics screen uses, with the portal's filters (regions, status classes,
// WAF outcomes) kept so the strings stay identical. The jest tests pin the output against
// strings generated by the portal's own functions.
import {
  buildHistogramQuantileQuery,
  buildPrometheusLabelSelector,
  buildRateQuery,
  createRegionFilter,
  REGION_LABEL,
  type PrometheusLabelFilter,
} from './promql';

export const ENVOY_RQ_METRIC = 'envoy_vhost_vcluster_upstream_rq';
export const ENVOY_RQ_TIME_METRIC = 'envoy_vhost_vcluster_upstream_rq_time_bucket';
export const CORAZA_EVENTS_METRIC = 'coraza_envoy_filter_request_events_total';

type Multi = string | readonly string[] | null | undefined;

export interface AlbQueryScope {
  projectId: string;
  /** HTTPProxy name (Envoy `gateway_name`). */
  proxyId: string;
  regions?: Multi;
  /** `2XX`…`5XX`. */
  statusClasses?: Multi;
  wafOutcomes?: Multi;
  wafSeverities?: Multi;
  requireRegion?: boolean;
  includeNamespace?: boolean;
  customLabels?: Record<string, string>;
}

const STATUS_CLASS_PATTERN: Record<string, string> = { '2XX': '2..', '3XX': '3..', '4XX': '4..', '5XX': '5..' };

/**
 * Tenant scoping is these labels and nothing else: the project label in the
 * PromQL, exactly as the portal does it (see `src/resources/metrics/source.ts`).
 */
export function albBaseLabels(projectId: string, proxyId: string, includeNamespace = true): Record<string, string> {
  return {
    resourcemanager_datumapis_com_project_name: projectId,
    gateway_name: proxyId,
    ...(includeNamespace ? { gateway_namespace: 'default' } : {}),
  };
}

export function toStatusClassPatterns(statusClasses: Multi): string[] {
  const values = Array.isArray(statusClasses) ? statusClasses : statusClasses ? [statusClasses as string] : [];
  return values.map((value) => STATUS_CLASS_PATTERN[value] ?? '').filter(Boolean);
}

function statusClassFilter(statusClasses: Multi): PrometheusLabelFilter {
  return { label: 'envoy_response_code', value: toStatusClassPatterns(statusClasses) };
}

export function resetGuardedIncrease(metric: string, selector: string, window: string): string {
  const series = `${metric}${selector}`;
  return `(increase(${series}[${window}]) * (resets(${series}[${window}]) == bool 0))`;
}

function trafficSelector(scope: AlbQueryScope): string {
  const requireRegion = scope.requireRegion ?? true;
  return buildPrometheusLabelSelector({
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId, scope.includeNamespace ?? true),
    customLabels: { ...(requireRegion ? { [REGION_LABEL]: '!=""' } : {}), ...scope.customLabels },
    filters: [createRegionFilter(scope.regions), statusClassFilter(scope.statusClasses)],
  });
}

/** WAF series carry no `gateway_namespace`. */
function wafSelector(scope: AlbQueryScope): string {
  const requireRegion = scope.requireRegion ?? true;
  return buildPrometheusLabelSelector({
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId, false),
    customLabels: { ...(requireRegion ? { [REGION_LABEL]: '!=""' } : {}), ...scope.customLabels },
    filters: [
      createRegionFilter(scope.regions),
      { label: 'coraza_outcome', value: scope.wafOutcomes },
      { label: 'coraza_rule_severity', value: scope.wafSeverities },
    ],
  });
}

export function albRpsQuery(scope: AlbQueryScope, timeWindow: string): string {
  return buildRateQuery({
    metric: ENVOY_RQ_METRIC,
    timeWindow,
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId, scope.includeNamespace ?? true),
    customLabels: { ...(scope.requireRegion === false ? {} : { [REGION_LABEL]: '!=""' }), ...scope.customLabels },
    filters: [createRegionFilter(scope.regions), statusClassFilter(scope.statusClasses)],
    groupBy: [],
  });
}

/**
 * Requests over `window`. `increase()` needs two samples, so a brand-new
 * series falls back to the raw counter.
 */
export function albRequestCountQuery(scope: AlbQueryScope, window: string): string {
  const series = `${ENVOY_RQ_METRIC}${trafficSelector(scope)}`;
  return `sum(increase(${series}[${window}])) or sum(${series})`;
}

/** Requests per second by `2XX`…`5XX` (`envoy_response_code_class`). */
export function albRpsByClassQuery(scope: AlbQueryScope, timeWindow: string): string {
  return (
    `sum by (envoy_response_code_class) (` +
    `label_replace(` +
    `rate(${ENVOY_RQ_METRIC}${trafficSelector(scope)}[${timeWindow}]),` +
    `"envoy_response_code_class","$\{1}XX","envoy_response_code","([0-9]).*"` +
    `))`
  );
}

export function albErrorRpsQuery(scope: AlbQueryScope, timeWindow: string): string {
  return buildRateQuery({
    metric: ENVOY_RQ_METRIC,
    timeWindow,
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId),
    customLabels: { [REGION_LABEL]: '!=""', envoy_response_code: '=~"[45].."', ...scope.customLabels },
    filters: [createRegionFilter(scope.regions), statusClassFilter(scope.statusClasses)],
    groupBy: [],
  });
}

/** 4xx + 5xx share of requests (0–1). Empty when there was no traffic. */
export function albErrorRateQuery(scope: AlbQueryScope, timeWindow: string): string {
  return `${albErrorRpsQuery(scope, timeWindow)} / ${albRpsQuery({ ...scope, statusClasses: undefined }, timeWindow)}`;
}

/** Upstream latency quantile in milliseconds. */
export function albLatencyQuantileQuery(quantile: number, scope: AlbQueryScope, timeWindow: string): string {
  return buildHistogramQuantileQuery({
    quantile,
    metric: ENVOY_RQ_TIME_METRIC,
    timeWindow,
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId),
    customLabels: { [REGION_LABEL]: '!=""', ...scope.customLabels },
    filters: [createRegionFilter(scope.regions)],
    groupBy: ['le'],
  });
}

/** p50, p95 and p99 as three series labelled `quantile="p50"` etc. */
export function albLatencyPercentilesQuery(scope: AlbQueryScope, timeWindow: string): string {
  const quantiles: [number, string][] = [
    [0.5, 'p50'],
    [0.95, 'p95'],
    [0.99, 'p99'],
  ];
  return quantiles
    .map(
      ([quantile, name]) =>
        `label_replace(${albLatencyQuantileQuery(quantile, scope, timeWindow)},"quantile","${name}","","")`
    )
    .join(' or ');
}

export function albRegionalRpsQuery(scope: AlbQueryScope, timeWindow: string): string {
  return buildRateQuery({
    metric: ENVOY_RQ_METRIC,
    timeWindow,
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId),
    customLabels: { [REGION_LABEL]: '!=""', ...scope.customLabels },
    filters: [createRegionFilter(scope.regions), statusClassFilter(scope.statusClasses)],
    groupBy: [REGION_LABEL],
  });
}

export function albWafIncreaseQuery(scope: AlbQueryScope, window: string): string {
  return `sum(${resetGuardedIncrease(CORAZA_EVENTS_METRIC, wafSelector(scope), window)})`;
}

/**
 * WAF events by `coraza_outcome` (allowed / blocked / dropped), summed over
 * buckets of `step`. As an instant query with `step` = the whole window, it
 * is the total per outcome for the window.
 */
export function albWafByOutcomeQuery(scope: AlbQueryScope, step: string): string {
  return (
    `sum by (coraza_outcome) (` +
    `sum_over_time(` +
    `${resetGuardedIncrease(CORAZA_EVENTS_METRIC, wafSelector(scope), '1m')}` +
    `[${step}:1m]))`
  );
}

/** WAF events the filter stopped: `coraza_outcome` blocked or dropped (the portal's "WAF blocked"). */
export const WAF_BLOCKED_LABELS: Record<string, string> = { coraza_outcome: '=~"blocked|dropped"' };

/**
 * Top WAF rules by events over `window`, one series per rule id × file ×
 * phase × severity × action × CRS version. Events with no rule (allowed
 * traffic) come back as one series with none of those labels.
 */
export function albWafTopRulesQuery(scope: AlbQueryScope, window: string, top = 20): string {
  return (
    `topk(${top}, sum by (` +
    `coraza_rule_id, coraza_rule_file, coraza_interruption_phase, ` +
    `coraza_rule_severity, coraza_rule_action, coraza_rule_version` +
    `) (` +
    `sum_over_time(` +
    `${resetGuardedIncrease(CORAZA_EVENTS_METRIC, wafSelector(scope), '1m')}` +
    `[${window}:1m]))` +
    `)`
  );
}

// ── Per region (the portal's "Active POPs" card, overview/active-pops-card.tsx) ──

/** 5xx requests per second by region. The Active POPs card counts 5xx only, not 4xx. */
export function albRegionalServerErrorRpsQuery(scope: AlbQueryScope, timeWindow: string): string {
  return buildRateQuery({
    metric: ENVOY_RQ_METRIC,
    timeWindow,
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId),
    customLabels: { [REGION_LABEL]: '!=""', envoy_response_code: '=~"5.."', ...scope.customLabels },
    filters: [createRegionFilter(scope.regions)],
    groupBy: [REGION_LABEL],
  });
}

/** Upstream latency quantile (ms) by region. */
export function albRegionalLatencyQuantileQuery(quantile: number, scope: AlbQueryScope, timeWindow: string): string {
  return buildHistogramQuantileQuery({
    quantile,
    metric: ENVOY_RQ_TIME_METRIC,
    timeWindow,
    baseLabels: albBaseLabels(scope.projectId, scope.proxyId),
    customLabels: { [REGION_LABEL]: '!=""', ...scope.customLabels },
    filters: [createRegionFilter(scope.regions)],
    groupBy: ['le', REGION_LABEL],
  });
}
